{
  "name": "magpie-sub2api",
  "version": "0.2.2",
  "description": "magpie provider plugin for any sub2api site: the key's models, and its subscription, quota or balance as magpie usage",
  "type": "module",
  "main": "./index.mjs",
  "exports": "./index.mjs",
  "files": [
    "index.mjs",
    "README.md",
    "README.en.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "./test/run.sh"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "magpie-plugin",
    "sub2api",
    "provider"
  ],
  "author": "Randy (broven)",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/broven/magpie-sub2api.git"
  },
  "homepage": "https://github.com/broven/magpie-sub2api#readme",
  "bugs": {
    "url": "https://github.com/broven/magpie-sub2api/issues"
  },
  "engines": {
    "node": ">=20"
  },
  "magpie": {
    "icon": "data:image/svg+xml;base64,",
    "options": {
      "sites": [
        {
          "id": "my-site",
          "name": "My sub2api",
          "url": "https://api.example.com"
        }
      ]
    }
  }
}
